import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { BACK, Burst, Captions, DEEP, FONT, FR_FPS, INK, OUT, PINK, Ribbon, WA, WHITE, WaIcon, cl, k, lin, pop } from "./OutubroRosa";

// ACADEMIA FALCON — Outubro Rosa, versão 2: o vídeo dela alternando com cenas de motion em tela cheia. A voz é a do
// vídeo original, contínua; quando a fala pede um destaque (Outubro Rosa, as modalidades, mega desconto, só para
// mulheres, o WhatsApp, "escrito Outubro Rosa") a tela vira motion e volta para ela na frase seguinte, com uma faixa
// passando em cada troca. Mesma identidade da versão 1 (rosa dos balões, branco, preto) e mesmas legendas.

const F = (s: number) => Math.round(s * FR_FPS) / FR_FPS;
// trocas vídeo ⇄ motion (segundos do vídeo original)
const C = { m1: F(1.65), v2: F(5.85), m2: F(10.0), v3: F(13.0), m3: F(14.5), pan: F(18.95), v4: F(23.1), m5: F(27.05), v5: F(28.68), m6: F(31.05), v6: F(33.08), m7: F(36.65), v7: F(39.42), m8: F(41.92), v8: F(45.22), end: F(46.5) };
const WIPES = [C.m1, C.v2, C.m2, C.v3, C.m3, C.pan, C.m5, C.v5, C.m6, C.v6, C.m7, C.v7, C.m8, C.v8];

const slam = (t: number, at: number, d = 0.24): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.8 - 0.8 * e).toFixed(3)})` };
};
const rise = (t: number, at: number, dy = 70, d = 0.4): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: e, transform: `translateY(${((1 - e) * dy).toFixed(1)}px)` };
};
const TXT: React.CSSProperties = { fontFamily: FONT, fontWeight: 900, textTransform: "uppercase", whiteSpace: "nowrap", lineHeight: 1, letterSpacing: "-0.02em" };
const col = (top: number, gap = 14): React.CSSProperties => ({ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap });

// faixa diagonal que atravessa a tela em cada troca
const Wipe: React.FC<{ t: number; at: number; i: number }> = ({ t, at, i }) => {
  const d = 0.2;
  if (t < at - d || t > at + d) return null;
  const dir = i % 2 ? -1 : 1;
  const x = (lin(t, at - d, at + d) * 2 - 1) * 1950 * dir;
  const c = [WHITE, DEEP, PINK][i % 3];
  const c2 = [PINK, WHITE, WHITE][i % 3];
  return (
    <div style={{ position: "absolute", left: 540 - 850, top: -200, width: 1700, height: 2320, transform: `translateX(${x.toFixed(0)}px) skewX(${-12 * dir}deg)`, background: c, boxShadow: `${90 * dir}px 0 0 ${c2}, ${-90 * dir}px 0 0 ${c2}` }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1000, display: "flex", justifyContent: "center", transform: `skewX(${12 * dir}deg)` }}>
        <Ribbon s={150} c={c === WHITE ? PINK : WHITE} />
      </div>
    </div>
  );
};

// fundos das cenas de motion
const BALLS = Array.from({ length: 11 }, (_, i) => ({ x: (i * 397 + 60) % 1080, s: 130 + ((i * 71) % 150), sp: 150 + ((i * 37) % 130), ph: (i * 433) % 2300 }));
const Bg: React.FC<{ t: number; kind: "pink" | "dark"; rays?: boolean }> = ({ t, kind, rays }) => (
  <AbsoluteFill style={{ background: kind === "pink" ? `linear-gradient(180deg, #FF58A8 0%, ${PINK} 30%, ${DEEP} 64%, #4A0027 100%)` : "radial-gradient(circle at 50% 34%, #6A0C3B 0%, #230714 55%, #0D0307 100%)" }}>
    {rays ? <div style={{ position: "absolute", left: -700, top: -300, width: 2480, height: 2480, background: `repeating-conic-gradient(from ${(t * 28).toFixed(1)}deg at 50% 50%, rgba(255,255,255,0.13) 0deg 8deg, rgba(255,255,255,0) 8deg 16deg)` }} /> : null}
    {BALLS.map((b, i) => {
      const y = 1920 + b.s - ((t * b.sp + b.ph) % (1920 + 2 * b.s));
      return <div key={i} style={{ position: "absolute", left: b.x - b.s / 2 + Math.sin(t * 0.9 + i) * 26, top: y, width: b.s, height: b.s * 1.12, borderRadius: "50%", background: kind === "pink" ? "radial-gradient(circle at 34% 28%, rgba(255,255,255,0.5) 0%, rgba(255,255,255,0.14) 42%, rgba(255,255,255,0.05) 75%)" : "radial-gradient(circle at 34% 28%, rgba(255,120,185,0.6) 0%, rgba(255,46,147,0.22) 45%, rgba(255,46,147,0.06) 78%)", opacity: 0.8 }} />;
    })}
    <div style={{ position: "absolute", left: -900, top: -300, width: 620, height: 2600, background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.2) 50%, rgba(255,255,255,0) 100%)", transform: `translateX(${(((t * 0.62) % 1) * 2900).toFixed(0)}px) skewX(-14deg)` }} />
    <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 700, background: "linear-gradient(180deg, rgba(30,0,14,0) 0%, rgba(30,0,14,0.72) 60%, rgba(20,0,10,0.9) 100%)" }} />
  </AbsoluteFill>
);
const Scene: React.FC<{ t: number; a: number; b: number; kind: "pink" | "dark"; rays?: boolean; children: React.ReactNode }> = ({ t, a, b, kind, rays, children }) => {
  if (t < a || t >= b) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Bg t={t} kind={kind} rays={rays} />
      <AbsoluteFill style={{ transform: `translate(${(Math.sin(t * 1.9) * 16).toFixed(1)}px, ${(Math.cos(t * 1.5) * 9).toFixed(1)}px) scale(${(1 + 0.06 * lin(t, a, b)).toFixed(4)}) rotate(${(Math.sin(t * 1.3) * 0.8).toFixed(2)}deg)`, transformOrigin: "50% 13%" }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const Pill: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; dark?: boolean }> = ({ t, at, children, size = 44, dark }) => (
  <div style={{ ...TXT, fontSize: size, color: dark ? WHITE : INK, background: dark ? INK : WHITE, borderRadius: 14, padding: "8px 26px 10px", boxShadow: "0 10px 24px rgba(0,0,0,0.35)", letterSpacing: 0, transform: `scale(${interpolate(t, [at, at + 0.35], [0, 1], { ...cl, easing: BACK }).toFixed(3)}) rotate(-2deg)` }}>{children}</div>
);
// janela com vídeo (piscina / musculação)
const Clip: React.FC<{ t: number; at: number; src: string; from?: number; w: number; h: number }> = ({ t, at, src, from = 0, w, h }) => (
  <div style={{ width: w, height: h, borderRadius: 40, overflow: "hidden", border: `9px solid ${WHITE}`, boxSizing: "border-box", boxShadow: "0 30px 70px rgba(0,0,0,0.55)", background: "#000" }}>
    <Sequence from={Math.round(at * FR_FPS)} layout="none">
      <OffthreadVideo src={staticFile(`falcon/${src}`)} trimBefore={Math.round(from * FR_FPS)} muted style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(1.05 + 0.1 * lin(t, at, at + 4)).toFixed(3)})` }} />
    </Sequence>
  </div>
);
const Label: React.FC<{ children: string; size?: number; inv?: boolean; style?: React.CSSProperties }> = ({ children, size = 96, inv, style }) => {
  const lines = children.split("\n");
  const fit = Math.min(size, 760 / (Math.max(...lines.map((l) => l.length)) * 0.74));
  return <div style={{ ...TXT, fontSize: fit, whiteSpace: "pre", textAlign: "center", color: inv ? WHITE : DEEP, background: inv ? `linear-gradient(135deg, ${PINK} 0%, ${DEEP} 100%)` : WHITE, borderRadius: 26, padding: "14px 36px 18px", boxShadow: inv ? `0 16px 40px rgba(0,0,0,0.45), 0 0 0 7px ${WHITE}` : "0 16px 40px rgba(0,0,0,0.4)", ...style }}>{children}</div>;
};

// ───────── cenas de motion ─────────
// 1 — "o Outubro Rosa e fazer uma nova atividade e cuidar mais de você?"
const M1: React.FC<{ t: number }> = ({ t }) => (
  <Scene t={t} a={C.m1} b={C.v2} kind="pink">
    <div style={col(238, 0)}>
      <svg width={176} height={229} viewBox="0 0 40 52" fill="none" stroke={WHITE} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round" style={{ transform: `rotate(${(Math.sin(t * 2.2) * 5).toFixed(2)}deg) scale(${pop(t, 1.68, 0.4).toFixed(3)})`, filter: "drop-shadow(0 12px 22px rgba(0,0,0,0.3))" }}>
        <path d="M9 47 L27 15 C31 8 26 4 20 4 C14 4 9 8 13 15 L31 47" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - lin(t, 1.68, 2.3)} />
      </svg>
    </div>
    <div style={col(490, 12)}>
      <div style={{ ...TXT, fontSize: 164, color: WHITE, textShadow: "0 10px 0 rgba(120,0,60,0.55)", ...slam(t, 1.75) }}>Outubro</div>
      <div style={slam(t, 2.35)}>
        <div style={{ ...TXT, fontSize: 196, color: DEEP, background: WHITE, borderRadius: 30, padding: "6px 44px 16px", transform: "rotate(-3deg)", boxShadow: "0 20px 46px rgba(0,0,0,0.4)" }}>Rosa</div>
      </div>
    </div>
    <div style={col(968, 12)}>
      <div style={{ ...TXT, fontSize: 42, color: WHITE, letterSpacing: "0.06em", ...rise(t, 2.77) }}>que tal fazer uma</div>
      <div style={{ ...TXT, fontSize: 82, color: WHITE, ...slam(t, 3.23) }}>nova atividade</div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, background: INK, borderRadius: 60, padding: "12px 34px 12px 24px", marginTop: 16, transform: `scale(${pop(t, 4.38, 0.4).toFixed(3)}) rotate(2deg)`, boxShadow: "0 12px 28px rgba(0,0,0,0.4)" }}>
        <svg width={52} height={48} viewBox="0 0 24 22" fill={PINK} style={{ transform: `scale(${(1 + 0.14 * Math.max(0, Math.sin(t * 9))).toFixed(3)})` }}>
          <path d="M12 21C5 15 1 11.500 1 7a5.500 5.500 0 0 1 11-1.500A5.500 5.500 0 0 1 23 7c0 4.500-4 8-11 14z" />
        </svg>
        <div style={{ ...TXT, fontSize: 46, color: WHITE, letterSpacing: 0 }}>e cuidar mais de você</div>
      </div>
    </div>
  </Scene>
);
// 2 — "Na musculação e nas nossas atividades aquáticas."
const M2: React.FC<{ t: number }> = ({ t }) => {
  const a = interpolate(t, [10.12, 10.6], [0, 1], { ...cl, easing: OUT });
  const b = interpolate(t, [11.24, 11.72], [0, 1], { ...cl, easing: OUT });
  return (
    <Scene t={t} a={C.m2} b={C.v3} kind="dark">
      <div style={col(244)}>
        <Pill t={t} at={10.02} size={46}>a promoção vale para</Pill>
      </div>
      <div style={{ position: "absolute", left: 96, top: 350, transform: `translateX(${((1 - a) * -700).toFixed(0)}px) rotate(${(-4 + Math.sin(t * 1.6) * 0.8).toFixed(2)}deg)` }}>
        <Clip t={t} at={10.05} src="principal.mp4" from={19.4} w={420} h={580} />
        <div style={{ position: "absolute", left: 0, right: 0, bottom: -44, display: "flex", justifyContent: "center" }}>
          <Label size={48} inv style={{ transform: `scale(${pop(t, 10.3, 0.35).toFixed(3)})`, padding: "10px 24px 12px", borderRadius: 18 }}>Musculação</Label>
        </div>
      </div>
      <div style={{ position: "absolute", left: 564, top: 560, transform: `translateX(${((1 - b) * 700).toFixed(0)}px) rotate(${(4 + Math.sin(t * 1.6 + 2) * 0.8).toFixed(2)}deg)` }}>
        <Clip t={t} at={11.2} src="b1.mp4" w={420} h={580} />
        <div style={{ position: "absolute", left: 0, right: 0, bottom: -92, display: "flex", justifyContent: "center" }}>
          <Label size={46} inv style={{ transform: `scale(${pop(t, 11.7, 0.35).toFixed(3)})`, padding: "10px 24px 12px", borderRadius: 18, lineHeight: 1.05 }}>{"Atividades\naquáticas"}</Label>
        </div>
      </div>
      <div style={{ position: "absolute", left: 484, top: 590, width: 112, height: 112, borderRadius: 56, background: WHITE, display: "flex", alignItems: "center", justifyContent: "center", ...TXT, fontSize: 96, color: DEEP, boxShadow: "0 12px 30px rgba(0,0,0,0.5)", transform: `scale(${pop(t, 11.14, 0.35).toFixed(3)}) rotate(${((1 - k(t, 11.14, 0.5)) * -180).toFixed(0)}deg)` }}>+</div>
    </Scene>
  );
};
// 3 — "hidroginástica e natação adulto ou musculação."
const OPTS: { at: number; src: string; from?: number; label: string }[] = [
  { at: 14.5, src: "b3.mp4", label: "Hidroginástica" },
  { at: 15.72, src: "b4.mp4", from: 1.2, label: "Natação adulto" },
  { at: 17.96, src: "principal.mp4", from: 20.6, label: "Musculação" },
];
const M3: React.FC<{ t: number }> = ({ t }) => (
  <Scene t={t} a={C.m3} b={C.pan} kind="pink">
    <div style={col(244)}>
      <Pill t={t} at={14.5} size={46}>você escolhe</Pill>
    </div>
    {OPTS.map((o, i) => {
      const next = OPTS[i + 1]?.at ?? 99;
      if (t < o.at - 0.02 || t > next + 0.4) return null;
      const e = interpolate(t, [o.at, o.at + 0.42], [0, 1], { ...cl, easing: OUT });
      const x = interpolate(t, [next, next + 0.38], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 344, display: "flex", flexDirection: "column", alignItems: "center", gap: 30, transform: `translateX(${((1 - e) * 1000 - x * 1050).toFixed(0)}px) rotate(${((1 - e) * 8 - x * 8 + (i % 2 ? 1.5 : -1.5)).toFixed(2)}deg)` }}>
          <Clip t={t} at={o.at} src={o.src} from={o.from} w={540} h={690} />
          <Label size={92} style={{ transform: `scale(${pop(t, o.at + 0.14, 0.38).toFixed(3)}) rotate(-2deg)` }}>{o.label}</Label>
          <div style={{ position: "absolute", left: 540 - 270 - 34, top: -34, width: 104, height: 104, borderRadius: 52, background: INK, color: WHITE, display: "flex", alignItems: "center", justifyContent: "center", ...TXT, fontSize: 60, border: `6px solid ${WHITE}`, boxSizing: "border-box", transform: `scale(${pop(t, o.at + 0.22, 0.35).toFixed(3)})` }}>{i + 1}</div>
        </div>
      );
    })}
    <div style={{ position: "absolute", left: 0, right: 0, top: 1262, display: "flex", justifyContent: "center", gap: 14 }}>
      {OPTS.map((o, i) => (
        <div key={i} style={{ width: t >= o.at && t < (OPTS[i + 1]?.at ?? 99) ? 54 : 18, height: 18, borderRadius: 9, background: WHITE, opacity: t >= o.at ? 1 : 0.4 }} />
      ))}
    </div>
  </Scene>
);
// pausa da fala (imagem da musculação do vídeo original): a marca da campanha
const Pan: React.FC<{ t: number }> = ({ t }) => {
  if (t < C.pan || t >= C.v4) return null;
  const out = 1 - interpolate(t, [22.75, 23.05], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(209,0,104,0.62) 0%, rgba(60,0,30,0.5) 50%, rgba(20,0,10,0.72) 100%)" }} />
      <div style={{ ...col(470, 16), transform: `scale(${((1 + 0.05 * lin(t, C.pan, C.v4)) * out).toFixed(4)})`, opacity: out, transformOrigin: "50% 30%" }}>
        <div style={{ transform: `scale(${pop(t, 19.12, 0.4).toFixed(3)}) rotate(${(Math.sin(t * 2.4) * 5).toFixed(2)}deg)` }}>
          <Ribbon s={120} c={WHITE} />
        </div>
        <div style={{ ...TXT, fontSize: 164, color: WHITE, textShadow: "0 10px 0 rgba(120,0,60,0.6)", ...slam(t, 19.32) }}>Outubro</div>
        <div style={slam(t, 19.62)}>
          <div style={{ ...TXT, fontSize: 190, color: DEEP, background: WHITE, borderRadius: 30, padding: "6px 44px 16px", transform: "rotate(-3deg)", boxShadow: "0 20px 46px rgba(0,0,0,0.45)" }}>Rosa</div>
        </div>
        <div style={{ ...TXT, fontSize: 52, color: WHITE, letterSpacing: "0.12em", marginTop: 22, ...rise(t, 20.15) }}>na Academia Falcon</div>
        <Label size={66} inv style={{ marginTop: 14, transform: `scale(${(pop(t, 20.75, 0.4) * (1 + 0.025 * Math.sin(t * 6))).toFixed(4)}) rotate(2deg)` }}>Só para mulheres</Label>
      </div>
    </AbsoluteFill>
  );
};
// 5 — "mega desconto"
const M5: React.FC<{ t: number }> = ({ t }) => {
  const sh = t > 27.19 && t < 27.5 ? 12 * (1 - (t - 27.19) / 0.31) : t > 27.55 && t < 27.85 ? 12 * (1 - (t - 27.55) / 0.3) : 0;
  return (
    <Scene t={t} a={C.m5} b={C.v5} kind="pink" rays>
      {[0, 1, 2, 3, 4, 5, 6].map((i) => {
        const u = lin(t, 27.22 + i * 0.03, 28.5);
        const ang = (i * 51 + 20) * (Math.PI / 180);
        return <div key={i} style={{ position: "absolute", left: 540 + Math.cos(ang) * (160 + u * 520) - 50, top: 700 + Math.sin(ang) * (200 + u * 640) - 50, ...TXT, fontSize: 110 + (i % 3) * 30, color: WHITE, opacity: 0.55 * Math.sin(Math.min(1, u * 1.2) * Math.PI), transform: `rotate(${(i * 40 + u * 120).toFixed(0)}deg)` }}>%</div>;
      })}
      <div style={{ ...col(250, 18), transform: `translate(${(Math.sin(t * 95) * sh).toFixed(1)}px, ${(Math.cos(t * 81) * sh).toFixed(1)}px)` }}>
        <Pill t={t} at={27.05} size={44}>qualquer modalidade com</Pill>
        <div style={{ ...TXT, fontSize: 268, color: WHITE, marginTop: 120, textShadow: "0 14px 0 rgba(120,0,60,0.6)", ...slam(t, 27.17) }}>Mega</div>
        <div style={slam(t, 27.53)}>
          <div style={{ ...TXT, fontSize: 134, color: DEEP, background: WHITE, borderRadius: 30, padding: "12px 40px 20px", transform: `rotate(-3deg) scale(${(1 + 0.03 * Math.sin(t * 8)).toFixed(4)})`, boxShadow: "0 22px 50px rgba(0,0,0,0.45)" }}>desconto</div>
        </div>
      </div>
    </Scene>
  );
};
// 6 — "é só pra você, mulher."
const M6: React.FC<{ t: number }> = ({ t }) => (
  <Scene t={t} a={C.m6} b={C.v6} kind="dark">
    <div style={col(246, 0)}>
      <svg width={190} height={253} viewBox="0 0 30 40" fill="none" stroke={PINK} strokeWidth={4.500} strokeLinecap="round" style={{ transform: `scale(${(pop(t, 31.05, 0.35) * (1 + 0.03 * Math.sin(t * 6))).toFixed(4)})`, filter: `drop-shadow(0 0 22px ${PINK})` }}>
        <circle cx={15} cy={12} r={9} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - lin(t, 31.05, 31.5)} />
        <path d="M15 21v16M8 30h14" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - lin(t, 31.4, 31.75)} />
      </svg>
    </div>
    <div style={col(560, 18)}>
      <div style={{ ...TXT, fontSize: 168, color: WHITE, ...slam(t, 31.2) }}>Só para</div>
      <div style={slam(t, 31.86)}>
        <div style={{ ...TXT, fontSize: 132, color: WHITE, background: `linear-gradient(135deg, ${PINK} 0%, ${DEEP} 100%)`, borderRadius: 30, padding: "12px 40px 20px", transform: "rotate(-3deg)", boxShadow: `0 22px 50px rgba(0,0,0,0.5), 0 0 0 8px ${WHITE}` }}>mulheres</div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 40, ...rise(t, 32.2) }}>
        <Ribbon s={34} />
        <div style={{ ...TXT, fontSize: 40, color: WHITE, letterSpacing: "0.04em" }}>promoção do Outubro Rosa</div>
      </div>
    </div>
  </Scene>
);
// 7 — "clique aqui agora no nosso WhatsApp."
const M7: React.FC<{ t: number }> = ({ t }) => {
  const tap = 37.92;
  const press = t > tap && t < tap + 0.15 ? 1 : 0;
  const hand = interpolate(t, [37.35, tap], [0, 1], { ...cl, easing: OUT });
  return (
    <Scene t={t} a={C.m7} b={C.v7} kind="dark">
      <div style={col(250)}>
        <Pill t={t} at={36.66} size={46}>faz o seguinte</Pill>
      </div>
      {[0, 0.5].map((dl) => {
        const u = t > tap ? (t - tap + dl) % 1 : -1;
        return u >= 0 ? <div key={dl} style={{ position: "absolute", left: 110, top: 430, width: 860, height: 520, borderRadius: 90, border: `8px solid ${WA}`, boxSizing: "border-box", opacity: 0.75 * (1 - u), transform: `scale(${(1 + u * 0.2).toFixed(3)})` }} /> : null;
      })}
      <div style={{ position: "absolute", left: 110, top: 430, width: 860, height: 520, borderRadius: 90, background: `linear-gradient(160deg, #3BE57A 0%, ${WA} 45%, #12A84C 100%)`, boxShadow: `0 30px 70px rgba(0,0,0,0.55), 0 0 0 9px ${WHITE}`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, transform: `scale(${(pop(t, 36.68, 0.45) * (1 - press * 0.06) * (1 + 0.02 * Math.sin(t * 7))).toFixed(4)})` }}>
        <div style={{ transform: `scale(${pop(t, 36.7, 0.4).toFixed(3)})` }}>
          <WaIcon s={132} />
        </div>
        <div style={{ display: "flex", gap: 24 }}>
          <div style={{ ...TXT, fontSize: 92, color: WHITE, ...slam(t, 36.73) }}>Clique</div>
          <div style={{ ...TXT, fontSize: 92, color: WHITE, ...slam(t, 37.05) }}>aqui</div>
        </div>
        <div style={{ ...TXT, fontSize: 150, color: WHITE, textShadow: "0 8px 0 rgba(0,90,40,0.6)", ...slam(t, 37.75) }}>agora</div>
      </div>
      {/* o cursor que toca no botão */}
