export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const BACK = Easing.out(Easing.back(1.7));
export const k = (t: number, a: number, d = 0.35) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const span = (t: number, a: number, b: number, d = 0.25) => pop(t, a, 0.4) * (1 - interpolate(t, [b - d, b], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) }));

