  if (i < 0) return null;
  const c = CAPS[i];
  const end = c.end ?? (i + 1 < CAPS.length ? CAPS[i + 1].words[0][1] - 0.06 : 1e9);
  if (t >= end) return null;
  const long = c.words.reduce((n, w) => n + w[0].length, 0) > 17;
  const size = long ? 62 : 72;
  return (
    <div style={{ position: "absolute", left: 60, right: 60, top: 1372, display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "center", columnGap: size * 0.26, rowGap: 10, fontFamily: FONT, fontWeight: 900, fontSize: size, lineHeight: 1.1, textTransform: "uppercase", letterSpacing: "-0.01em" }}>
      {c.words.map(([w, at, hl], j) => {
        const e = pop(t, at - 0.05, 0.3);
        return (
          <span key={j} style={{ display: "inline-block", opacity: t >= at - 0.06 ? 1 : 0, transform: `scale(${(0.6 + 0.4 * e).toFixed(3)}) rotate(${hl ? -2 : 0}deg)`, color: WHITE, background: hl ? PINK : undefined, padding: hl ? "2px 16px 4px" : undefined, borderRadius: 14, textShadow: hl ? "0 3px 0 rgba(0,0,0,0.25)" : "0 0 14px rgba(0,0,0,0.9), 0 4px 0 #000, 3px 0 0 #000, -3px 0 0 #000, 0 -3px 0 #000", boxShadow: hl ? "0 8px 22px rgba(0,0,0,0.35)" : undefined }}>{w}</span>
