// faixa grande de destaque (duas linhas), no alto
export const Burst: React.FC<{ t: number; a: number; b: number; top?: number; small?: string; big: string; size?: number; icon?: React.ReactNode }> = ({ t, a, b, top = 300, small, big, size = 124, icon }) => {
  if (t < a - 0.02 || t > b + 0.02) return null;
  const e = span(t, a, b);
  const lines = big.split("\n");
  const chars = Math.max(...lines.map((l) => l.length));
  const fit = Math.min(size, (800 - (icon ? 100 : 0)) / (chars * 0.74));
  const sh = t < a + 0.25 ? 9 * (1 - (t - a) / 0.25) : 0;
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 10, transform: `translate(${(Math.sin(t * 90) * sh).toFixed(1)}px, ${(Math.cos(t * 77) * sh).toFixed(1)}px) scale(${(e * (1 + 0.02 * Math.sin(t * 6))).toFixed(4)}) rotate(-3deg)`, opacity: Math.min(1, e * 3) }}>
